import React, { useContext, useState } from "react";
import { AuthContext } from "../context/AuthContext";
import "./Navbar.css";

const Navbar = ({ setPage }) => {
  const { user, logout } = useContext(AuthContext);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleNavClick = (page) => {
    setPage(page);
    setMobileMenuOpen(false);
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <div className="navbar-brand" onClick={() => handleNavClick("events")}>
          <span className="logo-icon">📅</span>
          <span className="logo-text">College Events</span>
        </div>

        <div className={`navbar-menu ${mobileMenuOpen ? "active" : ""}`}>
          <div className="navbar-nav">
            <button className="nav-link" onClick={() => handleNavClick("events")}>
              📍 Events
            </button>
            <button className="nav-link" onClick={() => handleNavClick("calendar")}>
              📆 Calendar
            </button>
            <button className="nav-link" onClick={() => handleNavClick("map")}>
              🗺️ Map
            </button>
            {user && user.role === "student" && (
              <button className="nav-link" onClick={() => handleNavClick("myEvents")}>
                ⭐ My Events
              </button>
            )}
            {user && user.role === "admin" && (
              <button className="nav-link admin" onClick={() => handleNavClick("admin")}>
                ⚙️ Admin Dashboard
              </button>
            )}
          </div>

          <div className="navbar-user">
            {user ? (
              <>
                <div className="user-info">
                  <span className="user-name">{user.name}</span>
                  <span className={`user-role ${user.role}`}>{user.role}</span>
                </div>
                <button className="btn-logout" onClick={logout}>
                  Logout
                </button>
              </>
            ) : (
              <>
                <button className="btn-auth btn-login" onClick={() => handleNavClick("login")}>
                  Sign In
                </button>
                <button className="btn-auth btn-register" onClick={() => handleNavClick("register")}>
                  Sign Up
                </button>
              </>
            )}
          </div>
        </div>

        <button
          className="navbar-toggle"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
        >
          ☰
        </button>
      </div>
    </nav>
  );
};

export default Navbar;
